import json
import re

from subprocess import PIPE, Popen

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result, log_warning
from taf.rfrl.procedures.resources.python.log_verifiers.exceptions import FileConversionError, ConversionFilterError, \
    BipLogDataLoadError, BipParameterValidationError, McsharkDecoderError


class BIPLogs:
    """
    Responsible for operations on BIP Logs.
    """
    def __init__(self):
        self._bip_log_data = None

    @log_input_and_output
    def check_mcshark_plugin(self, sw_version):
        """
        Checks if mcshark plugin is installed with the appropriate version.
        Logs warning message if mcshark version plugin is not the same as used BTS sw version.

        :param sw_version: current BTS SW version, i.e. 'SBTS25R3_ENB_9999_250603_000011'
        :type sw_version: str

        :raises McsharkDecoderError: if mcshark plugin is not installed or version verification was failed.
        """
        sw_version = self._convert_trunk_sw_version_name(sw_version)

        subproc = Popen("tshark -G plugins | grep mcshark", shell=True, stdout=PIPE, stderr=PIPE)
        stdout, stderr = subproc.communicate()

        stdout = stdout.decode('utf-8')
        stderr = stderr.decode('utf-8')

        if re.search(r"mcshark-\d.*", stdout):
            if sw_version not in stdout:
                log_warning(f"Incompatible mcshark decoder version for current SW '{sw_version}': '{stdout}'")
            else:
                log_result("Mcshark decoder version is correct.")
            return
        elif not stdout and not stderr:
            error_msg = "Mcshark decoder is not installed."
        else:
            error_msg = f"Mcshark decoder version validation failed: stdout: '{stdout}', stderr: '{stderr}'."

        raise McsharkDecoderError(error_msg)

    def convert_bip_log_file_to_json(self, bip_path, filter=None, alternative_filter=None, json_custom_path=None):
        """
        Converts BIP Log PCAP file to json file using tshark with mcshark plugin.
        It is recommended to use filters during pcap conversion to prevent by json data overload.

        :param bip_path: absolute path to BIP Log file with pcap extension, e.g.: '/home/ute/bip_logs/tcpdump.pcap'
        :type bip_path: str
        :param filter: filters defined as packages names used during pcap conversion,
                       e.g.: 'uldata_pucchreceivereq || uldata_pucchreceiverespps'
                       Defaults to None means that pcap conversion will be performed without any filters.
        :type filter: str or None
        :param alternative_filter: alternative filters defined as packages names used during pcap conversion if main
                                   filter doesnn't work,
                                   e.g.: 'uldata_pucchreceivereql1sw || uldata_pucchreceiveresppsl1sw'
                                   Defaults to None means that pcap conversion will be performed only with main filter
                                   if it was defined.
        :type alternative_filter: str or None
        :param json_custom_path: absolute path to json file including extension to create after BIP Log conversion,
                                 e.g.: '/home/ute/converted_bip/new_bip.json'
                                 Defaults to None means that json file will be created in the same location with the
                                 same filename as converted BIP Log PCAP file.
        :type json_custom_path: str or None
        :return: absolute path to created json file, e.g.: "/home/ute/json_file.json"
        :rtype: str

        :raises ConversionFilterError: when BIP Log file cannot be converted with given filters
        """
        json_path = json_custom_path if json_custom_path is not None else bip_path.replace(".pcap", ".json")

        try:
            json_path = self._convert_pcap_to_json_file(path_to_pcap=bip_path, path_to_json=json_path, filter=filter)
            return json_path
        except ConversionFilterError:
            if alternative_filter is not None:
                try:
                    json_path = self._convert_pcap_to_json_file(path_to_pcap=bip_path, path_to_json=json_path,
                                                                filter=alternative_filter)
                    return json_path
                except ConversionFilterError:
                    raise FileConversionError(f"PCAP file could not be filtered by used phrases: '{filter}' and "
                                              f"'{alternative_filter}'.")
            else:
                raise FileConversionError(f"PCAP file could not be filtered by used phrase: '{filter}'.")

    def load_bip_logs_data_from_json(self, json_path):
        """
        Loads BIP Logs data from converted json file.

        :param json_path: absolute path with extension to converted BIP Log json file,
                          e.g.: '/home/ute/bip_logs/tcpdump.json'
        :type json_path: str
        """
        with open(json_path, "r") as json_file:
            json_content = json.loads(json_file.read(),
                                      object_pairs_hook=self._json_loads_convert_duplicated_keys_to_json_array)

            self._bip_log_data = json_content

    @log_input_and_output
    def validate_numOfSymbols_CB007449(self):
        """
        Validates 'numOfSymbols' parameters for feature CB007449. BIP Log data must be loaded before validation.
        Validation based on 'numOfSymbols' parameters value check.
        Value of 'numOfSymbols' should be always equal '14' in all PUCCH resources. Values '0' can be ignored.

        :raises BipLogDataLoadError: when BIP Log data was not loaded before validation.
        :raises BipParameterValidationError: when 'numOfSymbols' parameter is not validated successfully.
        """
        self._check_if_bip_log_data_is_loaded()

        numOfSymbols = self._get_data_from_json(self._bip_log_data,
                                                "UlData_pucchReceiveReqPucchResource(|L1sw)_t.numOfSymbols")
        for numOfSymbol in numOfSymbols:
            if str(numOfSymbol) != '0' and str(numOfSymbol) != '14':
                raise BipParameterValidationError(f"Expected value of numOfSymbol for LongPucch formats is '14'. "
                                                  f"Current value is: '{numOfSymbol}'")

        log_result("'numOfSymbols' validation succeeded!")

    @log_input_and_output
    def validate_pattern_ids_CB007449(self):
        """
        Validates 'patternIDs' parameters of Format 1 and Format 3 for feature CB007449. BIP Log data must be loaded
        before validation. Validation based on 'patternIDs' parameters value check for Format 1 and Format 3.
        PatternIDs of Format 1 (received using sector beam) should be the same for all PUCCH resources.
        PatternIDs of Format 3 (received using SSB beams) should be different than patternIDs of Format 1 when CB007449
        feature is active.

        :raises BipLogDataLoadError: when BIP Log data was not loaded before validation.
        :raises BipParameterValidationError: when 'patternIDs' parameters are not validated successfully.
        """
        self._check_if_bip_log_data_is_loaded()

        format_1_patterns = []
        format_3_patterns = []

        for msg in self._bip_log_data:
            pucch_resources = self._get_data_from_json(msg, "nr_l1ul_l2ps_uldata_pucchreceivereqpucchresource(|L1sw)_t")

            if pucch_resources:
                pucch_resources = self._split_pucch_resources_to_separated_items(pucch_resources)

                for pucch_resource in pucch_resources:
                    pucch_format_data = self._get_data_from_json(
                        pucch_resource, "UlData_pucchReceiveReqPucchResource(|L1sw)_t.pucchFormat")

                    self._validate_pucchFormat_in_pucchresource(pucch_format_data, pucch_resource)

                    pucch_format = pucch_format_data[0]

                    if str(pucch_format) == "3":
                        f3_pattern_results = self._get_data_from_json(
                            pucch_resource, "UlData_pucchReceiveReqPucchResource(|L1sw)_t.patternId_item")
                        format_3_patterns.append(f3_pattern_results[0])

                    elif str(pucch_format) == "1":
                        f1_pattern_results = self._get_data_from_json(
                            pucch_resource, "UlData_pucchReceiveReqPucchResource(|L1sw)_t.patternId_item")
                        format_1_patterns.append(f1_pattern_results[0])

        self._validate_pattern_ids_for_pucch_format_1_and_3_CB007449(format_1_patterns=format_1_patterns,
                                                                     format_3_patterns=format_3_patterns)

        log_result("'pattern_ids' validation succeeded!")

    @log_input_and_output
    def validate_uci_bits_CB007449(self):
        """
        Validates 'UCIBits' parameters for feature CB007449. BIP Log data must be loaded before validation.
        Validation based on 'UCIBits' parameters value check.
        'UCIBits' parameters should exist for all uldata_pucchep data frames. 'uci' (NR Physical channels and modulation
        PUCCH UCI) parameters should exist for all uldata_pucchep data frames except for the first frame.
        Parameter 'an' (AckNack) should exist under all 'uci' (NR Physical channels and
        modulation PUCCH UCI) parameters.

        :raises BipLogDataLoadError: when BIP Log data was not loaded before validation.
        :raises BipParameterValidationError: when 'UCIBits' parameters are not validated successfully.
        """
        self._check_if_bip_log_data_is_loaded()

        ul_data_pucch_ep_list = []
        for msg in self._bip_log_data:
            ul_data_pucch_eps = self._get_data_from_json(msg, "nr_l1ul_l2ps_uldata_pucchep(|l1sw)")

            if ul_data_pucch_eps:
                ul_data_pucch_ep_list += ul_data_pucch_eps

        for uldata_pucch_ep in ul_data_pucch_ep_list:
            if not uldata_pucch_ep.get("uci.pucch.ucibits"):
                raise BipParameterValidationError("Missing 'uci.pucch.ucibits' information in 'uldata_pucchep' msg!")

        for uldata_pucch_ep in ul_data_pucch_ep_list[1:]:

            if not uldata_pucch_ep.get("nr-phy.pucch.uci"):
                raise BipParameterValidationError("Missing 'nr-phy.pucch.uci' information in 'uldata_pucchep' msg!")

            if not uldata_pucch_ep["nr-phy.pucch.uci"].get("uci.an"):
                raise BipParameterValidationError("Missing 'uci.an' information in 'nr-phy.pucch.uci' msg!")

        log_result("'UCIBits' validation succeeded!")

    @log_input_and_output
    def validate_srbit_detection_CB007449(self, number_of_ues):
        """
        Validates 'srBitDetection' parameter for feature CB007449. BIP Log data must be loaded before validation.
        Validation based on 'srBitDetection' parameter value check for all PUCCH resources of PUCCH Foramt 1.
        At least one of frame with enabled `srBitDetection` parameter should be found when more than 2 UEs are
        used during L3call transmission. When less than 2 UE are used during L3call transmission it may happen that
        no `srBitDetection` parameter is enabled.

        :param number_of_ues: number of UEs used during L3call
        :type number_of_ues: int or str

        :raises BipLogDataLoadError: when BIP Log data was not loaded before validation.
        :raises BipParameterValidationError: when 'srBitDetection' parameter is not validated successfully.
        """
        self._check_if_bip_log_data_is_loaded()

        srBitDetection_is_enabled = False
        for msg in self._bip_log_data:
            pucch_resources = self._get_data_from_json(msg, "nr_l1ul_l2ps_uldata_pucchreceivereqpucchresource(|L1sw)_t")

            if pucch_resources:
                for pucch_resource in pucch_resources:
                    pucchFormat = self._get_data_from_json(
                        pucch_resource, "UlData_pucchReceiveReqPucchResource(|L1sw)_t.pucchFormat")

                    if pucchFormat == "1":
                        srBitDetection = self._get_data_from_json(
                            pucch_resource, "UlData_pucchReceiveReqPucchResource(|L1sw)_t.srBitDetection")

                        if srBitDetection == "1":
                            srBitDetection_is_enabled = True

        if not srBitDetection_is_enabled:
            if int(number_of_ues) > 2:
                raise BipParameterValidationError("At least one of frame with enabled `srBitDetection` parameter "
                                                  "should be found when count of used UEs is greater than 2.")
            else:
                log_warning("Frame not found with 'srBitDetection' parameter enabled. It could be related to not "
                            "enough count of used UEs.")

        log_result("'srBitDetection' validation succeeded!")

    @log_input_and_output
    def _validate_pattern_ids_for_pucch_format_1_and_3_CB007449(self, format_1_patterns, format_3_patterns):
        """
        Validates 'patternIDs' parameters for Format 1 and Format 3 for feature CB007449.
        """
        if not format_1_patterns or not format_3_patterns:
            raise BipParameterValidationError("PatternIDs of PUCCH Format 1 and Format 3 can't be empty!")

        if format_1_patterns.count(format_1_patterns[0]) != len(format_1_patterns):
            raise BipParameterValidationError(
                f"PatternIDs of PUCCH Format 1 should be the same for all resources: {format_1_patterns}")
        else:
            log_result("PUCCH Format 1 patternIDs validation succeeded!")

        for format_3_pattern in format_3_patterns:
            if format_3_pattern == format_1_patterns[0]:
                raise BipParameterValidationError(
                    "PatternIDs of PUCCH Format 3 should be always different than PatternIDs of PUCCH Format 1!")
        else:
            log_result("PUCCH Format 3 patternIDs validation succeeded!")

    def _check_if_bip_log_data_is_loaded(self):
        """
        Checks if any BIP Log data has been loaded before validation.
        """
        if self._bip_log_data is None:
            raise BipLogDataLoadError("Please load BIP file before validation!")

    @staticmethod
    def _json_loads_convert_duplicated_keys_to_json_array(ordered_pairs):
        """
        Converts duplicated keys to JSON array.
        This method is used as object_pairs_hook parameter in json.loads method.
        """
        conv_dict = {}
        for key, value in ordered_pairs:
            if key in conv_dict:
                if type(conv_dict[key]) is list:
                    conv_dict[key].append(value)
                else:
                    conv_dict[key] = [conv_dict[key], value]
            else:
                conv_dict[key] = value
        return conv_dict

    def _get_data_from_json(self, json_object, target_key, case_insensitive_mode=True):
        """
        Gets data recursively from json.
        """
        result = []
        self._parse_json_recursively(json_object=json_object, target_key=target_key, result=result,
                                     case_insensitive_mode=case_insensitive_mode)

        return result

    def _parse_json_recursively(self, json_object, target_key, result, case_insensitive_mode):
        """
        Parses json's data recursively.
        """
        case_insensitive_regex_prefix = "(?i)" if case_insensitive_mode else ""

        if type(json_object) is dict and json_object:
            for key in json_object:
                if re.fullmatch(rf"{case_insensitive_regex_prefix}{target_key}", key):
                    result.append(json_object[key])
                self._parse_json_recursively(json_object[key], target_key, result, case_insensitive_mode)

        elif type(json_object) is list and json_object:
            for item in json_object:
                self._parse_json_recursively(item, target_key, result, case_insensitive_mode)

    @staticmethod
    def _split_pucch_resources_to_separated_items(pucch_resources):
        """
        Splits PUCCH resources if they contain more than one resources item.
        """
        separated_resources = []
        for pucch_resource in pucch_resources:
            if isinstance(pucch_resource, dict):
                separated_resources.append(pucch_resource)
            elif isinstance(pucch_resource, list):
                for item in pucch_resource:
                    if isinstance(item, dict):
                        separated_resources.append(item)

        return separated_resources

    @staticmethod
    def _validate_pucchFormat_in_pucchresource(pucch_format_data, pucch_resource):
        """
        Validates number of `pucchFormat` in pucch Format data of particular pucch resource.
        Pucch Format data should contain only one `pucchFormat` message.
        """
        if len(pucch_format_data) > 1:
            raise BipParameterValidationError(f"Found more than one 'pucchFormat' variable in "
                                              f"pucchResource: {pucch_resource}")
        elif not pucch_format_data:
            raise BipParameterValidationError(f"'PucchFormat' not found in pucchResource: {pucch_resource}")

    @staticmethod
    @log_input_and_output
    def _convert_pcap_to_json_file(path_to_pcap, path_to_json, filter=None):
        """
        Converts pcap to json file using thark with mcshark decoder and particular filters.
        """
        filtering_phrase = f" -Y '{filter}'" if filter else ""

        subproc = Popen(f"""tshark -r {path_to_pcap}{filtering_phrase} -T json > {path_to_json}""",
                        shell=True, stdout=PIPE, stderr=PIPE)
        stdout, stderr = subproc.communicate()

        if "is neither a field nor a protocol name" in stderr.decode('utf-8'):
            raise ConversionFilterError(f"Conversion failed - incorrect filter: {stderr.decode('utf-8')}")

        if stdout.decode('utf-8') == "" and stderr.decode('utf-8') == "":
            return path_to_json
        else:
            raise FileConversionError(f"Conversion failed - unknown problem. Stdout: {stdout.decode('utf-8')}, "
                                      f"stderr: {stderr.decode('utf-8')}")

    @staticmethod
    def _convert_trunk_sw_version_name(sw_version):
        if "_9999_" in sw_version:
            sw_ver = re.sub(r"SBTS\d\dR\d_", "SBTS00_", sw_version)
        else:
            sw_ver = sw_version

        return sw_ver
